from jinja2 import Template


def render_message(recipient: str, body: str) -> str:
    """Render a local message template and wrap it in the NotifyHub layout."""
    rendered_body = Template(body).render(recipient=recipient)
    return f"To: {recipient}\n\n{rendered_body}\n\n— Sent with NotifyHub"
